__GASH_CALL_COMMON="GASH_HEADLESS NO_COLOR GASH_NO_COLOR GASH_DEBUG GASH_TUI COLUMNS GASH_DIR GASH_ENV_FILE LANG LC_ALL LC_CTYPE"
